/**
 * SectionHead — encabezado de un bloque de formulario (mi-garaje-lab · Flujo Valorizar, paso Detalles: Mecánica, Estado del
 * vehículo…; y Publicar, paso Información: Datos de la publicación, Ubicación, Equipamiento…).
 * Ícono de Vidrio de 36 px, título 16/700 y, según el bloque: check naranja cuando está completo, una nota de AVT a la derecha
 * con la ⓘ de Concorde, o el estado «Faltan N» (borde teal de Negociable con punto que late), «Listo» u «Opcional».
 * Depende de React, Vidrio, CheckIcon e InfoIcon.
 */
import type { JSX } from "react";
import { Vidrio, type Sec } from "@/concorde/components/Vidrio";
import CheckIcon from "@/concorde/components/CheckIcon";
import InfoIcon from "@/concorde/components/InfoIcon";

export const SECTION_HEAD_CSS = String.raw`
.fl-sh { display:flex; align-items:center; gap:12px; }
.fl-sh__ico { display:grid; place-items:center; width:36px; height:36px; color:#5A35C2; }
.fl-sh__txt { min-width:0; display:grid; gap:2px; }
.fl-sh__txt small { font-size:.875rem; color:#6B6878; }
.fl-sh .fl-sub__t { margin:0; display:inline-flex; align-items:center; gap:8px; font-size:1rem; font-weight:700; color:#3B1782; }
.fl-sh .fl-gdone { display:inline-grid; animation:fl-sh-pop .35s cubic-bezier(.2,1.4,.4,1) both; }
.fl-sh .fl-gtip { margin-left:auto; display:inline-flex; align-items:center; gap:6px; font-size:.75rem; font-weight:600; color:#5A35C2; white-space:nowrap; }
.fl-sh__st { display:inline-flex; align-items:center; gap:6px; height:24px; padding:0 10px 0 8px; border-radius:9999px; font-size:.75rem; font-weight:700; white-space:nowrap; color:#006E70;
  border:1px solid transparent; background:linear-gradient(#fff,#fff) padding-box, linear-gradient(90deg,#00A8AB,#8460E5) border-box; box-shadow:0 2px 8px rgba(0,168,171,.18); }
.fl-sh__st::before { content:""; width:6px; height:6px; border-radius:50%; background:linear-gradient(135deg,#30E8EC,#00A8AB); box-shadow:0 0 0 2px rgba(0,168,171,.18); animation:fl-sh-pulse 2s ease-in-out infinite; }
.fl-sh__st.is-ok, .fl-sh__st.is-opt { gap:4px; padding:0 10px; border:0; box-shadow:none; }
.fl-sh__st.is-ok::before, .fl-sh__st.is-opt::before { content:none; }
.fl-sh__st.is-ok { color:#3B1782; background:#F5F0FF; animation:fl-sh-pop .36s cubic-bezier(.16,1,.3,1); }
.fl-sh__st.is-opt { font-weight:600; color:#6B6878; background:#F3F2F6; }
@keyframes fl-sh-pop { from { opacity:0; transform:scale(.5); } }
@keyframes fl-sh-pulse { 50% { opacity:.35; transform:scale(.7); } }
@media (max-width:640px) { .fl-sh { flex-wrap:wrap; } .fl-sh .fl-gtip { flex-basis:100%; margin-left:48px; } }
@media (prefers-reduced-motion:reduce) { .fl-sh .fl-gdone, .fl-sh__st.is-ok, .fl-sh__st::before { animation:none; } }
`;

export interface SectionHeadProps {
  /** Ícono de Vidrio del bloque (p. ej. «caja» para Mecánica, «ubicacion» para Ubicación). */
  icon: Sec;
  /** Título del bloque. */
  title: string;
  /** id del título (para aria-labelledby de la sección). */
  titleId?: string;
  /** Bajada bajo el título (p. ej. «Completa lo que no indicaste en la valorización»). */
  hint?: string;
  /** Bloque completo: check naranja junto al título. */
  done?: boolean;
  /** Nota de AVT a la derecha, con la ⓘ (p. ej. «típico · toca para cambiar»). */
  tip?: string;
  /** Estado a la derecha del título: cuántos datos faltan, «ok» (Listo) u «optional» (Opcional). */
  status?: number | "ok" | "optional";
}

export function SectionHead({ icon, title, titleId, hint, done, tip, status }: SectionHeadProps): JSX.Element {
  return <>
    <style href="concorde-section-head" precedence="default">{SECTION_HEAD_CSS}</style>
    <div className="fl-sh"><span className="fl-sh__ico vd-host" aria-hidden><Vidrio s={icon} size={36} /></span>
      <div className="fl-sh__txt"><h2 id={titleId} className="fl-sub__t">{title}{done ? <span key="ok" className="fl-gdone"><CheckIcon size={20} title="Completo" /></span> : null}</h2>{hint ? <small>{hint}</small> : null}</div>
      {tip ? <span className="fl-gtip"><InfoIcon size={16} />{tip}</span> : null}
      {status === undefined ? null : status === "optional" ? <span className="fl-sh__st is-opt">Opcional</span>
        : status === "ok" ? <span key="ok" className="fl-sh__st is-ok"><CheckIcon size={14} /> Listo</span>
        : <span className="fl-sh__st">{status === 1 ? "Falta 1" : `Faltan ${status}`}</span>}
    </div>
  </>;
}

export default SectionHead;

"use client";

import { useId, type JSX, type ReactNode } from "react";

/** Estilos del componente (antes en vidrio.css). Se inyectan una sola vez por página. */
export const VIDRIO_CSS = String.raw`
/* Íconos de vidrio esmerilado (Vidrio.tsx): capas, movimiento y estados. Compartido por /iconos y Mi Garaje. */
/* sólido violeta detrás, vidrio lila translúcido delante (ver Vidrio.tsx). */
.vd { --solid:#5A35C2; --glass:#B9A6F2; display:block; overflow:visible; }
.vd * { transform-box:view-box; }
.vd-bk, .vd-bl { color:var(--solid); fill:var(--solid); }
.vd-glass { fill:var(--glass); fill-opacity:.72; }
.vd-edge { fill:none; stroke:#fff; stroke-opacity:.45; stroke-width:1.5; }

/* Movimiento del vidrio (15/10). Pauta: 150–300 ms, una sola pasada, solo transform/opacity, resorte leve y nada con «reducir movimiento».
 * 1) Parallax: al pasar, el vidrio sube y el sólido baja: las capas se separan. La copia desenfocada (vd-bl) compensa para seguir al sólido.
 * 2) Gesto propio de cada ícono, una vez. */
.vd { --spring:linear(0, .25 5%, .55 11%, .8 18%, .96 26%, 1.04 34%, 1.06 40%, 1.05 47%, 1.02 58%, 1 70%, .995 82%, 1); --out:cubic-bezier(.25,.8,.25,1); }
.vd-bk, .vd-gl, .vd-bl, .vd-asa, .vd-nd, .vd-card, .vd-pt { transition:transform .18s var(--out); }
.vd-host:is(:hover,:focus-visible,.is-hover,.is-focus):not(.is-dis,:disabled) :is(.vd-bk, .vd-gl, .vd-bl, .vd-asa, .vd-nd, .vd-card, .vd-pt) { transition:transform .32s var(--spring); }
.vd-host:is(:hover,:focus-visible,.is-hover,.is-focus):not(.is-dis,:disabled) .vd-bk { transform:translate(1px,1.5px); }
.vd-host:is(:hover,:focus-visible,.is-hover,.is-focus):not(.is-dis,:disabled) .vd-gl { transform:translate(0,-1.5px); }
.vd-host:is(:hover,:focus-visible,.is-hover,.is-focus):not(.is-dis,:disabled) .vd-bl { transform:translate(1px,3px); }
/* Negociaciones: los tres puntos «escriben». */
.vd-host:is(:hover,:focus-visible,.is-hover,.is-focus):not(.is-dis,:disabled) .vd-dot { animation:vd-hop .36s var(--out); }
.vd-host:is(:hover,:focus-visible,.is-hover,.is-focus):not(.is-dis,:disabled) .vd-dot:nth-child(2) { animation-delay:.06s; } .vd-host:is(:hover,:focus-visible,.is-hover,.is-focus):not(.is-dis,:disabled) .vd-dot:nth-child(3) { animation-delay:.12s; }
@keyframes vd-hop { 40% { transform:translateY(-2.5px); } }
/* Participaciones: el martillo golpea. */
.vd--participaciones .vd-gx { transform-origin:30px 30px; }
.vd-host:is(:hover,:focus-visible,.is-hover,.is-focus):not(.is-dis,:disabled) .vd--participaciones .vd-gx { animation:vd-strike .42s var(--out); }
@keyframes vd-strike { 35% { transform:rotate(-14deg); } 65% { transform:rotate(4deg); } }
/* Compras: el asa se levanta y el check se dibuja. */
.vd-host:is(:hover,:focus-visible,.is-hover,.is-focus):not(.is-dis,:disabled) .vd-asa { transform:translateY(-2px); }
.vd-ck { stroke-dasharray:1; }
.vd-host:is(:hover,:focus-visible,.is-hover,.is-focus):not(.is-dis,:disabled) .vd-ck { animation:vd-draw .32s .06s var(--out) backwards; }
@keyframes vd-draw { from { stroke-dashoffset:1; } to { stroke-dashoffset:0; } }
/* Publicaciones: la etiqueta se balancea desde el agujero. */
.vd--publicaciones .vd-gx { transform-origin:17px 18px; }
.vd-host:is(:hover,:focus-visible,.is-hover,.is-focus):not(.is-dis,:disabled) .vd--publicaciones .vd-gx { animation:vd-swing .5s var(--out); }
@keyframes vd-swing { 25% { transform:rotate(9deg); } 55% { transform:rotate(-5deg); } 80% { transform:rotate(2deg); } }
/* Valorizaciones: la aguja sube y se queda mientras pasas. */
.vd-nd { transform-origin:24px 33px; }
.vd-host:is(:hover,:focus-visible,.is-hover,.is-focus):not(.is-dis,:disabled) .vd-nd { transform:rotate(22deg); }
/* Billetera: la tarjeta sale. */
.vd-host:is(:hover,:focus-visible,.is-hover,.is-focus):not(.is-dis,:disabled) .vd-card { transform:translateY(-3px); }
/* Auto: rebota sobre la suspensión. */
.vd-host:is(:hover,:focus-visible,.is-hover,.is-focus):not(.is-dis,:disabled) .vd--auto .vd-gx { animation:vd-bump .4s var(--out); }
@keyframes vd-bump { 30% { transform:translateY(-2.5px); } 60% { transform:translateY(.5px); } }
/* Alertas: la campana suena y el punto late. */
.vd--alertas .vd-gx { transform-origin:24px 8px; } .vd-pt { transform-origin:35px 11px; }
.vd-host:is(:hover,:focus-visible,.is-hover,.is-focus):not(.is-dis,:disabled) .vd--alertas .vd-gx { animation:vd-ring .5s var(--out); }
.vd-host:is(:hover,:focus-visible,.is-hover,.is-focus):not(.is-dis,:disabled) .vd-pt { transform:scale(1.15); }
@keyframes vd-ring { 20% { transform:rotate(12deg); } 45% { transform:rotate(-9deg); } 70% { transform:rotate(4deg); } }
.vd-host:is(:hover,:focus-visible,.is-hover,.is-focus):not(.is-dis,:disabled) .vd-bd { animation:vd-clap .5s .04s var(--out); }
@keyframes vd-clap { 20% { transform:translateX(-2.5px); } 45% { transform:translateX(2px); } 70% { transform:translateX(-1px); } }
/* Mi Garaje: aviso suena como alertas; dar de baja en naranja de marca, la tapa se levanta; republicar, la flecha da la vuelta. */
.vd--aviso .vd-gx { transform-origin:24px 10px; }
.vd-host:is(:hover,:focus-visible,.is-hover,.is-focus):not(.is-dis,:disabled) .vd--aviso .vd-gx { animation:vd-ring .5s var(--out); }
.vd--baja { --solid:#ED8936; --glass:#FFC995; }
.vd--republicar .vd-gx { transform-origin:21px 27px; }
.vd-host:is(:hover,:focus-visible,.is-hover,.is-focus):not(.is-dis,:disabled) .vd--baja .vd-gx { animation:vd-clap .45s var(--out); }
.vd-host:is(:hover,:focus-visible,.is-hover,.is-focus):not(.is-dis,:disabled) .vd--republicar .vd-gx { animation:vd-turn .5s var(--out); }
@keyframes vd-turn { to { transform:rotate(360deg); } }
@media (prefers-reduced-motion:reduce) { .vd * { animation:none !important; transition:none !important; } }

/* ── Estados del ícono (15/10). La clase is-* fuerza el estado en la matriz; en la interfaz real lo dan :hover, :focus-visible,
   :active, aria-current/aria-pressed y disabled. ── */
.vd-btn { all:unset; box-sizing:border-box; position:relative; display:grid; place-items:center; width:64px; height:64px; margin:0 auto; border-radius:16px; cursor:pointer; transition:background .15s, box-shadow .15s; }
.vd-btn:is(:hover,.is-hover,:focus-visible,.is-focus) { background:#F5F0FF; }
.vd-btn:is(:focus-visible,.is-focus) { outline:2px solid #8460E5; outline-offset:2px; }
.vd-btn .vd { transition:transform .09s var(--out, ease-out); }
/* Presionado: gana sobre hover (doble clase); las capas vuelven a juntarse y el ícono se hunde. */
.vd-host.vd-host:is(:active,.is-press):not(.is-dis,:disabled) { background:#EDE6FF; }
.vd-host.vd-host:is(:active,.is-press):not(.is-dis,:disabled) .vd { transform:scale(.94); }
.vd-host.vd-host:is(:active,.is-press):not(.is-dis,:disabled) :is(.vd-bk,.vd-gl,.vd-bl) { transform:none; transition-duration:.09s; }
.vd-host.vd-host:is(:active,.is-press) .vd-glass { fill-opacity:.85; }
/* Seleccionado: naranja de marca (ítem activo de VMC) + barra inferior como señal que no depende del color. */
.vd-host:is([aria-current=page],[aria-pressed=true],.is-sel) .vd { --solid:#ED8936; --glass:#FFC995; }
.vd-btn:is([aria-current=page],[aria-pressed=true],.is-sel) { background:#FFF3E6; }
.vd-btn:is([aria-current=page],[aria-pressed=true],.is-sel)::after { content:""; position:absolute; left:20px; right:20px; bottom:5px; height:3px; border-radius:3px; background:#ED8936; }
/* Deshabilitado: gris, sin movimiento, sin foco (disabled nativo). */
.vd-host:is(:disabled,.is-dis) { cursor:not-allowed; }
.vd-host:is(:disabled,.is-dis) .vd { --solid:#A9A6B5; --glass:#E2E0E9; }
.vd-host:is(:disabled,.is-dis) .vd * { animation:none !important; transition:none !important; }
`;

/** «Vidrio esmerilado» (15/10): dos formas por ícono, una sólida detrás y una de vidrio delante que la desenfoca donde
 *  se cruzan, con el detalle en blanco. Referencia: sets de íconos glassmorphism de Dribbble/Figma (p. ej. Glazicons).
 *  ponytail: el vidrio es SVG puro (copia desenfocada de la forma de atrás, recortada por la de adelante), no backdrop-filter:
 *  se ve igual en todos los navegadores y se exporta tal cual a Figma. Retícula de 48 px. */
export type Sec = "negociaciones" | "participaciones" | "compras" | "publicaciones" | "valorizaciones" | "billetera" | "auto" | "alertas" | "publicar" | "km" | "caja" | "combustible" | "fecha" | "ubicacion" | "equipo" | "docs" | "texto" | "precio" | "vehicular" | "equipos" | "maquinaria" | "materiales" | "articulos" | "mobiliario" | "empresa" | "verificado" | "crecimiento" | "vender" | "aviso" | "bolsa" | "republicar" | "baja";

type Parts = { back: ReactNode; front: ReactNode; detail: ReactNode };
const W = { fill: "none", stroke: "#fff", strokeWidth: 3, strokeLinecap: "round", strokeLinejoin: "round" } as const;
const T = { fill: "#fff", fontSize: 10, fontWeight: 800, textAnchor: "middle", fontFamily: "'Plus Jakarta Sans', sans-serif" } as const;

const PARTS: Record<Sec, Parts> = {
  // Dos globos: el de la contraparte (sólido) y el tuyo (vidrio).
  negociaciones: {
    back: <path d="M24 6h12a6 6 0 0 1 6 6v8a6 6 0 0 1-6 6v5l-6-5h-6a6 6 0 0 1-6-6v-8a6 6 0 0 1 6-6z" />,
    front: <path d="M12 15h14a7 7 0 0 1 7 7v7a7 7 0 0 1-7 7h-8l-7 6v-6.3A7 7 0 0 1 5 29v-7a7 7 0 0 1 7-7z" />,
    detail: <g fill="#fff"><circle className="vd-dot" cx="13" cy="25.5" r="2" /><circle className="vd-dot" cx="19" cy="25.5" r="2" /><circle className="vd-dot" cx="25" cy="25.5" r="2" /></g>,
  },
  // Martillo de subasta compacto: base como bloque y mango sólidos, cabeza de vidrio sobre el mango.
  participaciones: {
    back: <><path d="M21 18l15 15" fill="none" stroke="currentColor" strokeWidth={5} strokeLinecap="round" /><rect x="6" y="36" width="22" height="7" rx="3.5" /></>,
    front: <rect x="7" y="9.5" width="26" height="14" rx="5" transform="rotate(-40 20 16.5)" />,
    detail: <path d="M22.4 8.3l6.2 7.4M11.4 17.3l6.2 7.4" {...W} strokeWidth={2} />,
  },
  // Asa sólida detrás, bolsa de vidrio con check.
  compras: {
    back: <path className="vd-asa" d="M15 21v-6a9 9 0 0 1 18 0v6" fill="none" stroke="currentColor" strokeWidth={4.5} strokeLinecap="round" />,
    front: <path d="M11.4 16h25.2a3 3 0 0 1 3 2.8l1.3 19.4a4 4 0 0 1-4 4.3H11.1a4 4 0 0 1-4-4.3l1.3-19.4a3 3 0 0 1 3-2.8z" />,
    detail: <><circle cx="15" cy="22" r="2" fill="#fff" /><circle cx="33" cy="22" r="2" fill="#fff" /><path className="vd-ck" d="M18.5 30.5l4 4 7.5-7.5" pathLength={1} {...W} /></>,
  },
  // Etiqueta de vidrio (con S/) sobre una tarjeta sólida girada, como la etiqueta «%» de la referencia.
  publicaciones: {
    back: <rect x="22" y="7" width="20" height="20" rx="5" transform="rotate(18 32 17)" />,
    front: <path d="M17.5 9.4a2.5 2.5 0 0 1 3 0l7.6 6.4a3 3 0 0 1 1 2.3V39a3 3 0 0 1-3 3H12a3 3 0 0 1-3-3V18.1a3 3 0 0 1 1-2.3z" transform="rotate(-12 19 26)" />,
    detail: <g transform="rotate(-12 19 26)"><circle cx="19" cy="18" r="2.2" fill="#fff" /><text x="19" y="34" {...T}>S/</text></g>,
  },
  // Aguja sólida que asoma detrás del dial de vidrio, como el check de la referencia.
  valorizaciones: {
    back: <path className="vd-nd" d="M24 33L37 12" fill="none" stroke="currentColor" strokeWidth={5} strokeLinecap="round" />,
    front: <path d="M7 34a17 17 0 0 1 34 0v1a4 4 0 0 1-4 4H11a4 4 0 0 1-4-4z" />,
    detail: <><circle cx="24" cy="33" r="3" fill="#fff" /><path d="M13 31.5h1.5M17 23.5l1 1M34.5 31.5H33" {...W} strokeWidth={2.5} /></>,
  },
  // Billetera de vidrio con S/ y una tarjeta sólida asomando, como la billetera de la referencia.
  billetera: {
    back: <g className="vd-card"><rect x="12" y="6" width="24" height="17" rx="4" transform="rotate(-10 24 14)" /></g>,
    front: <rect x="6" y="15" width="36" height="27" rx="7" />,
    detail: <text x="24" y="33.5" {...T} fontSize={12}>S/</text>,
  },
  // Auto de frente: cabina y ruedas sólidas, carrocería de vidrio con faros.
  auto: {
    back: <><path d="M12.5 23l3.6-8.4a4 4 0 0 1 3.7-2.6h8.4a4 4 0 0 1 3.7 2.6l3.6 8.4z" /><rect x="9" y="32" width="7" height="9" rx="2.5" /><rect x="32" y="32" width="7" height="9" rx="2.5" /></>,
    front: <rect x="6" y="21" width="36" height="15" rx="6" />,
    detail: <><circle cx="13" cy="28.5" r="2.3" fill="#fff" /><circle cx="35" cy="28.5" r="2.3" fill="#fff" /><path d="M20.5 28.5h7" {...W} strokeWidth={2.5} /></>,
  },
  // Campana de vidrio; badajo y punto de aviso sólidos detrás.
  alertas: {
    back: <><circle className="vd-pt" cx="35" cy="11" r="7" /><circle className="vd-bd" cx="24" cy="38" r="4.5" /></>,
    front: <path d="M24 7a11 11 0 0 1 11 11v8l3.5 5a1.5 1.5 0 0 1-1.2 2.5H10.7A1.5 1.5 0 0 1 9.5 31l3.5-5v-8A11 11 0 0 1 24 7z" />,
    detail: <path d="M18 20a6 6 0 0 1 4-5.5" {...W} strokeWidth={2.5} />,
  },
  // Ficha del vehículo (16/10, vista rápida de la negociación): kilometraje, transmisión, combustible y fecha de publicación.
  // Kilometraje: odómetro de vidrio sobre una ruta sólida.
  km: {
    back: <path d="M16 42l5-30h6l5 30z" />,
    front: <rect x="5" y="9" width="38" height="18" rx="6" />,
    detail: <text x="24" y="22.5" {...T} fontSize={11}>km</text>,
  },
  // Transmisión: patrón en H sólido, pomo de vidrio arriba.
  caja: {
    back: <path d="M12 22v18M24 22v18M36 22v18M12 31h24" fill="none" stroke="currentColor" strokeWidth={4.5} strokeLinecap="round" />,
    front: <circle cx="24" cy="13" r="9" />,
    detail: <circle cx="24" cy="13" r="2.5" fill="#fff" />,
  },
  // Combustible: manguera sólida, surtidor de vidrio con visor.
  combustible: {
    back: <path d="M30 14h4l5 6v15a3 3 0 0 1-6 0v-7h-3" fill="none" stroke="currentColor" strokeWidth={4} strokeLinecap="round" strokeLinejoin="round" />,
    front: <rect x="8" y="7" width="22" height="35" rx="5" />,
    detail: <rect x="12.5" y="12" width="13" height="9" rx="2.5" fill="#fff" />,
  },
  // Fecha: anillas sólidas, hoja de vidrio con días.
  fecha: {
    back: <><rect x="13" y="4" width="6" height="12" rx="3" /><rect x="29" y="4" width="6" height="12" rx="3" /></>,
    front: <rect x="6" y="10" width="36" height="32" rx="7" />,
    detail: <g fill="#fff"><circle cx="16" cy="25" r="2.2" /><circle cx="24" cy="25" r="2.2" /><circle cx="32" cy="25" r="2.2" /><circle cx="16" cy="33" r="2.2" /><circle cx="24" cy="33" r="2.2" /></g>,
  },
  // Publicar VMC (16/10): ubicación, equipamiento, documentos y descripción con la misma receta (sólido detrás, vidrio delante).
  // Ubicación: sombra en el suelo sólida, pin de vidrio con su punto.
  ubicacion: {
    back: <><ellipse cx="24" cy="41" rx="13" ry="4" /><circle cx="35" cy="12" r="6" /></>,
    front: <path d="M24 5a13 13 0 0 1 13 13c0 9.5-13 23-13 23S11 27.5 11 18A13 13 0 0 1 24 5z" />,
    detail: <circle cx="24" cy="18" r="4.5" fill="#fff" />,
  },
  // Equipamiento: círculo sólido detrás, estrella de vidrio con check.
  equipo: {
    back: <circle cx="34" cy="13" r="9" />,
    front: <path d="M24 6l5.3 11.3 12.3 1.5-9.1 8.4 2.4 12.2L24 33.3 13.1 39.4l2.4-12.2-9.1-8.4 12.3-1.5z" />,
    detail: <path d="M19.5 24.5l3 3 6-6" {...W} strokeWidth={2.5} />,
  },
  // Documentos: hoja sólida detrás, hoja de vidrio delante con renglones.
  docs: {
